const v42Style=document.createElement('style');
v42Style.textContent=`#penalty-screen{max-width:900px}.v42-setup{margin-top:22px}.v42-setup-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.v42-setup label{display:block;font-size:12px;color:#b6cac7}.v42-setup select{display:block;width:100%;min-height:48px;margin-top:6px;padding:10px;border:1px solid #63787b;border-radius:7px;background:#102126;color:#fff;font:inherit}.v42-arena{position:relative;overflow:hidden;border:1px solid #6b9b7b;border-radius:12px;background:repeating-linear-gradient(90deg,#205440 0 58px,#275e49 58px 116px);min-height:340px;padding:22px;text-align:center}.v42-score{display:flex;align-items:center;justify-content:space-between;gap:9px;padding:11px;background:#102126d9;border-radius:8px;font-weight:800}.v42-score strong{font-size:30px;color:#eaffb5}.v42-goal{position:relative;width:min(80%,360px);height:115px;margin:30px auto 55px;border:6px solid #edf7ec;border-bottom:0;background:repeating-linear-gradient(90deg,#ffffff18 0 12px,#ffffff45 12px 14px);box-shadow:0 8px 20px #0005}.v42-keeper{position:absolute;bottom:-10px;left:50%;transform:translateX(-50%);font-size:42px}.v42-ball{position:absolute;left:50%;bottom:70px;transform:translateX(-50%);font-size:34px}.v42-last{min-height:36px;margin:20px 0 0;font-weight:800}.v42-last.good{color:#c7f36b}.v42-last.bad{color:#ffd29e}.v42-controls{display:flex;gap:10px;flex-wrap:wrap;margin:16px 0}.v42-controls button{flex:1;min-width:180px}.v42-kicks{display:grid;grid-template-columns:1fr 1fr;gap:7px;max-height:260px;overflow:auto}.v42-kicks article{padding:9px;background:#102126;border-radius:6px;font-size:12px}.v42-kicks .goal{color:#d9ffaf}.v42-kicks .miss{color:#ffd29e}.v42-modal{width:min(94vw,640px);max-height:86vh;overflow:auto;padding:20px;border:1px solid #8ccde8;border-radius:12px;background:#1a2a2f;color:#edf7ee;box-shadow:0 20px 60px #0009}.v42-modal::backdrop{background:#051111d9}.v42-modal h2{font-size:24px}.v42-order-list{margin:15px 0}.v42-order-row{display:grid;grid-template-columns:25px minmax(0,1fr) 80px;gap:8px;align-items:center;padding:9px 4px;border-bottom:1px solid #405458}.v42-order-row.recommended{background:#c7f36b10}.v42-order-row b{font-size:13px}.v42-order-row small{display:block;color:#a8bfba;font-size:11px;margin-top:4px}.v42-order-row .v42-badges{font-size:11px;color:#d6e8e0}.v42-order-row button{min-width:34px;min-height:36px;margin-left:3px;border:1px solid #627a7c;border-radius:5px;background:#263e42;color:#fff}.v42-tag{display:inline-block;padding:3px 6px;margin-left:6px;border-radius:4px;background:#4b6632;color:#edffc9;font-size:10px}.v42-celebration{position:absolute;left:12px;right:12px;top:78px;z-index:2}.v42-celebration .cup-celebration{margin:0;background:#102126e8}.v42-demo-card{margin-top:16px}.v42-demo-card .help{margin-bottom:12px}@media(max-width:600px){.v42-setup-grid{grid-template-columns:1fr}.v42-arena{min-height:310px;padding:12px}.v42-score{font-size:11px}.v42-score strong{font-size:24px}.v42-order-row{grid-template-columns:22px minmax(0,1fr) 78px}}`;
document.head.append(v42Style);
v42Style.textContent+=`.v42-score{display:grid;grid-template-columns:minmax(0,1fr) auto minmax(0,1fr)}.v42-score span{min-width:0;overflow-wrap:anywhere}.v42-score span:first-child{text-align:left;color:var(--v42-own)}.v42-score span:last-child{text-align:right;color:var(--v42-opp)}.v42-score strong{white-space:nowrap}.v42-ball.goal{animation:v42ShotGoal .6s ease-out both}.v42-ball.miss{animation:v42ShotMiss .6s ease-out both}@keyframes v42ShotGoal{to{transform:translate(-50%,-95px) scale(.55)}}@keyframes v42ShotMiss{to{transform:translate(30px,-70px) scale(.55)}}@media(prefers-reduced-motion:reduce){.v42-ball.goal,.v42-ball.miss{animation:none}}`;
v42Style.textContent+=`.v42-pitch-stage{position:relative}.v42-pitch-stage .cup-celebration{position:absolute;z-index:5;left:5%;right:5%;top:42%;margin:0;transform:translateY(-50%);background:#142b34ed;box-shadow:0 16px 48px #0009;pointer-events:none}@media(max-width:600px){.v42-pitch-stage .cup-celebration{left:3%;right:3%;padding:16px 9px}.v42-pitch-stage .cup-celebration h2{font-size:18px}}`;
v42Style.textContent+=`.v42-goal-scene{position:relative;isolation:isolate;width:min(100%,570px);height:300px;margin:18px auto 8px;overflow:hidden;border-radius:8px;background:linear-gradient(#283b41 0 34%,#205440 34% 100%)}.v42-goal-scene:after{content:"";position:absolute;z-index:0;inset:70% 0 0;background:repeating-linear-gradient(90deg,#ffffff0a 0 38px,#0000000c 38px 76px);pointer-events:none}.v42-stands{position:absolute;inset:0 0 auto;height:108px;display:grid;grid-template-columns:repeat(20,1fr);align-content:center;gap:5px 3px;padding:8px 12px;background:repeating-linear-gradient(0deg,#18252b 0 21px,#314047 21px 26px);border-bottom:5px solid #a5afb188}.v42-fan{position:relative;z-index:1;display:block;width:12px;height:10px;margin:auto;border-radius:6px 6px 2px 2px;background:var(--fan);box-shadow:0 1px 2px #0008}.v42-fan:before{content:"";position:absolute;left:3px;bottom:8px;width:6px;height:6px;border-radius:50%;background:#d8b99b}.v42-goal-scene.celebrate .v42-fan{animation:v42Cheer .45s ease-in-out 3 alternate}.v42-goal-scene .v42-goal{position:absolute;z-index:2;top:79px;left:50%;width:min(72%,360px);height:126px;margin:0;transform:translateX(-50%);border:7px solid #f2f5ed;border-bottom:5px solid #d6dcd4;border-radius:5px 5px 2px 2px;background:#c9d8d01f;box-shadow:inset 0 0 0 4px #84959366,8px 9px 0 #0005,0 8px 30px #0008}.v42-net{position:absolute;inset:4px;background:repeating-linear-gradient(0deg,transparent 0 17px,#dcead082 17px 19px),repeating-linear-gradient(90deg,transparent 0 19px,#dcead082 19px 21px);transform-origin:center bottom}.v42-goal-scene.goal .v42-net{animation:v42Net .65s ease-out}.v42-goal-scene .v42-keeper{position:absolute;z-index:4;left:50%;bottom:10px;display:grid;place-items:center;width:43px;height:43px;border:3px solid #f6d6a5;border-radius:50%;background:#e5b56a;color:#33291a;font:800 17px Arial,sans-serif;transform:translateX(-50%);box-shadow:0 6px 0 #0004}.v42-keeper:after{content:"🧤";position:absolute;right:-12px;top:-13px;font-size:22px}.v42-goal-scene.save .v42-keeper{animation:v42KeeperSave .7s ease-out both}.v42-goal-scene .v42-ball{position:absolute;z-index:5;left:50%;bottom:26px;font-size:27px;line-height:1;transform:translateX(-50%);filter:drop-shadow(1px 4px 1px #0007)}.v42-goal-scene .v42-ball.goal{animation:v42BallGoal .75s ease-out both}.v42-goal-scene .v42-ball.save{animation:v42BallSave .75s ease-out both}.v42-goal-scene .v42-ball.wide{animation:v42BallWide .75s ease-out both}.v42-goal-scene .v42-ball.high{animation:v42BallHigh .75s ease-out both}.v42-shooter{position:absolute;z-index:3;bottom:7px;left:28%;display:flex;align-items:center;gap:7px;max-width:47%;padding:5px 7px;border-radius:7px;background:#102126ce;text-align:left}.v42-shooter svg{width:43px;height:46px;flex:none;filter:drop-shadow(2px 4px 2px #0008)}.v42-shooter span{min-width:0;color:#fff;font-size:11px;font-weight:800;overflow-wrap:anywhere}.v42-next-shooter{min-height:20px;margin:4px 0 0;color:#d5e6d9;font-size:11px}@keyframes v42BallGoal{to{left:calc(50% + var(--shot-x));bottom:143px;transform:translateX(-50%) scale(.55)}}@keyframes v42BallSave{to{left:calc(50% + var(--shot-x));bottom:113px;transform:translateX(-50%) scale(.65)}}@keyframes v42BallWide{to{left:calc(50% + var(--miss-x));bottom:129px;transform:translateX(-50%) scale(.65)}}@keyframes v42BallHigh{to{left:calc(50% + var(--shot-x));bottom:267px;transform:translateX(-50%) scale(.65)}}@keyframes v42KeeperSave{to{transform:translateX(calc(-50% + var(--shot-x))) rotate(var(--dive-angle))}}@keyframes v42Net{40%{transform:scale(1.04,1.16)}100%{transform:scale(1)}}@keyframes v42Cheer{to{transform:translateY(-5px)}}@media(max-width:600px){.v42-goal-scene{height:270px}.v42-stands{grid-template-columns:repeat(16,1fr)}.v42-stands .v42-fan:nth-child(n+49){display:none}.v42-shooter{left:8%;max-width:57%}.v42-shooter svg{width:34px;height:38px}.v42-shooter span{font-size:10px}}@media(prefers-reduced-motion:reduce){.v42-goal-scene .v42-ball.goal{animation:none;left:calc(50% + var(--shot-x));bottom:143px;transform:translateX(-50%) scale(.55)}.v42-goal-scene .v42-ball.save{animation:none;left:calc(50% + var(--shot-x));bottom:113px;transform:translateX(-50%) scale(.65)}.v42-goal-scene .v42-ball.wide{animation:none;left:calc(50% + var(--miss-x));bottom:129px;transform:translateX(-50%) scale(.65)}.v42-goal-scene .v42-ball.high{animation:none;left:calc(50% + var(--shot-x));bottom:267px;transform:translateX(-50%) scale(.65)}.v42-goal-scene.save .v42-keeper{animation:none;transform:translateX(calc(-50% + var(--shot-x))) rotate(var(--dive-angle))}.v42-goal-scene.goal .v42-net,.v42-goal-scene.celebrate .v42-fan{animation:none}}`;

function v42Composure(player){if(Number.isFinite(player.composure))return player.composure;const hash=[...String(player.pid||player.name||'')].reduce((sum,char)=>sum*31+char.charCodeAt(0),0)>>>0;player.composure=clamp(Math.round(48+hash%35+((player.age||25)-25)*.4),25,95);return player.composure}
function v42PenaltyChance(shooter,keeper){const finish=shooter.fin??Math.round((shooter.pas||55)*.72);return clamp(.50+(finish-60)*.005+(v42Composure(shooter)-60)*.003+(shooter.form||0)*.02-(100-(shooter.fresh??100))*.0012-((keeper.gk||70)-60)*.003-(v42Composure(keeper)-60)*.001,.25,.9)}
v41PenaltyChance=v42PenaltyChance;
function v42Level(value){return value>=78?'sehr gut':value>=66?'gut':value>=52?'ordentlich':value>=40?'schwach':'sehr schwach'}
function v42Player(player,source=player){return{n:player.n,name:player.name,keeper:Boolean(player.keeper),fin:player.fin,pas:player.pas,gk:player.gk,form:source.form??player.form??0,fresh:source.fresh??player.fresh??100,composure:v42Composure(source),age:player.age}}
function v42Rank(player){return (player.fin??(player.pas||55)*.72)*.55+v42Composure(player)*.35+(player.form||0)*4+(player.fresh??100)*.05}
function v42Sorted(players){return[...players].sort((a,b)=>v42Rank(b)-v42Rank(a))}
function v42OrderHTML(session){const recommendedNumbers=new Set(v42Sorted(session.own).slice(0,3).map(player=>player.n));return session.order.map((number,index)=>{const player=session.own.find(item=>item.n===number),recommended=recommendedNumbers.has(number);return`<div class="v42-order-row ${recommended?'recommended':''}"><b>${index+1}.</b><div><strong>${escapeHTML(player.name)}</strong>${player.keeper?' <span class="v42-tag">TW</span>':''}${recommended?' <span class="v42-tag">Empfehlung</span>':''}<small>Abschluss: ${v42Level(player.fin??(player.pas||55)*.72)} · Ruhe: ${v42Level(v42Composure(player))} · ${freshText(player.fresh)}</small></div><div><button type="button" data-v42-move="${index}" data-v42-dir="-1" aria-label="${escapeHTML(player.name)} nach oben" ${index===0?'disabled':''}>↑</button><button type="button" data-v42-move="${index}" data-v42-dir="1" aria-label="${escapeHTML(player.name)} nach unten" ${index===5?'disabled':''}>↓</button></div></div>`}).join('')}

const v42Teams=[
 {id:'elite-rot',name:'Rotstadt Elite',level:'Sehr stark',colour:'#d94747',trim:'#fff0d8',fin:84,calm:83,gk:86,names:['Lena Stark','Nico Brandt','Mila Berg','Tarek Wolf','Sara König','Robin Falk']},
 {id:'elite-blau',name:'Blauwerk 66',level:'Sehr stark',colour:'#2979cb',trim:'#e4f5ff',fin:82,calm:86,gk:84,names:['Alex Winter','Mara Seidel','Jonas Voss','Elif Kaya','Tom Richter','Noah Sturm']},
 {id:'amateur-gruen',name:'Grünfeld Amateure',level:'Eher schwach',colour:'#459d58',trim:'#f3ffdb',fin:49,calm:47,gk:48,names:['Paul Wiese','Lea Kurz','Eren Yilmaz','Ben Vogt','Nina Holz','Luis Pohl']},
 {id:'amateur-gelb',name:'Gelbstern SV',level:'Eher schwach',colour:'#e3b943',trim:'#28343b',fin:46,calm:51,gk:46,names:['Jana Fink','Leon Berger','Max Eder','Anja Maurer','Emil Kern','Luca Hofer']}
];
function v42DemoRoster(team){return team.names.map((name,index)=>({n:[2,4,6,7,9,1][index],name,keeper:index===5,fin:index===5?Math.round(team.fin*.55):team.fin+[2,-3,0,4,5][index],pas:team.fin-3,gk:index===5?team.gk:0,form:0,fresh:100,composure:team.calm+[0,3,-4,5,2,-2][index],age:25}))}
function v42Colour(id){const team=v42Teams.find(item=>item.id===id);return{main:team?.colour||'#c7f36b',trim:team?.trim||'#fff'}}
let v42Session=null;
const v42Screen=document.createElement('main');v42Screen.id='penalty-screen';v42Screen.hidden=true;startScreen.before(v42Screen);
const v42DemoCard=document.createElement('section');v42DemoCard.className='panel v42-demo-card';v42DemoCard.innerHTML=`<h2>Elfmeterschießen testen</h2><p class="help">Wähle zwei von vier Demo-Teams. Zwei sind sehr stark, zwei eher schwach. Das Ergebnis verändert keine Karriere.</p><div class="v42-setup-grid"><label>Dein Team<select id="v42-own-team">${v42Teams.map(team=>`<option value="${team.id}">${team.name} · ${team.level}</option>`).join('')}</select></label><label>Gegner<select id="v42-opp-team">${v42Teams.map((team,index)=>`<option value="${team.id}" ${index===2?'selected':''}>${team.name} · ${team.level}</option>`).join('')}</select></label></div><p id="v42-demo-status" class="help" role="status"></p><button type="button" id="v42-demo-start" class="primary">Elfmeterschießen starten <span>↗</span></button>`;
startScreen.querySelector('.menu-layout').insertAdjacentElement('afterend',v42DemoCard);
$('#v42-demo-start').onclick=()=>{const own=$('#v42-own-team').value,opp=$('#v42-opp-team').value;if(own===opp){$('#v42-demo-status').textContent='Wähle zwei unterschiedliche Mannschaften.';return}$('#v42-demo-status').textContent='';const first=v42Teams.find(team=>team.id===own),second=v42Teams.find(team=>team.id===opp),ours=v42DemoRoster(first),theirs=v42DemoRoster(second);v42Session={mode:'demo',ownName:first.name,opponentName:second.name,ownColour:v42Colour(own),opponentColour:v42Colour(opp),own:ours,opponent:theirs,order:v42Sorted(ours).map(player=>player.n),opponentOrder:v42Sorted(theirs).map(player=>player.n),score:[0,0],kicks:[],phase:'choose',ownId:own,opponentId:opp};v42RenderScreen(true)};

function v42UpcomingShooter(session){if(session.phase!=='shooting')return null;const side=session.kicks.length%2,order=side===0?session.order:session.opponentOrder,roster=side===0?session.own:session.opponent;return{side,player:roster.find(item=>item.n===order[Math.floor(session.kicks.length/2)%6])}}
function v42OutcomeText(kick){return kick.outcome==='save'?'Gehalten!':kick.outcome==='wide'?'Vorbei!':kick.outcome==='high'?'Drüber!':kick.goal?'Tor!':'Kein Tor.'}
function v42Shirt(player,colour){return`<svg viewBox="0 0 80 85" role="img" aria-label="Trikot Nummer ${player.n}"><path d="M18 11 29 4h22l11 7 14 14-10 15-9-5v43H23V35l-9 5L4 25z" fill="${escapeHTML(colour.main)}" stroke="${escapeHTML(colour.trim)}" stroke-width="4" stroke-linejoin="round"/><text x="40" y="51" fill="${textColor(colour.main)}" font-family="Arial,sans-serif" font-weight="800" font-size="27" text-anchor="middle">${player.n}</text></svg>`}
function v42SceneHTML(session){
 const next=v42UpcomingShooter(session),last=session.last,side=last?.side??next?.side??0,roster=side===0?session.own:session.opponent,player=last?roster.find(item=>item.n===last.number):next?.player,colour=side===0?session.ownColour:session.opponentColour,keeper=(side===0?session.opponent:session.own).find(item=>item.keeper),direction=last?.shotSide??1;
 const fans=Array.from({length:64},(_,index)=>`<span class="v42-fan" style="--fan:${escapeHTML(index%3===0?session.ownColour.main:index%3===1?session.opponentColour.main:'#bdc5b5')}"></span>`).join('');
 return`<div class="v42-goal-scene${last?.goal?' celebrate':''}" style="--shot-x:${direction*64}px;--miss-x:${direction*44}%;--dive-angle:${direction*22}deg" aria-hidden="true"><div class="v42-stands">${fans}</div><div class="v42-goal"><div class="v42-net"></div><span class="v42-keeper">${keeper?.n??1}</span></div><span class="v42-ball">⚽</span>${player?`<div class="v42-shooter">${v42Shirt(player,colour)}<span>${escapeHTML(player.name)}</span></div>`:''}</div><p class="v42-next-shooter">${next?`${last?'Als Nächstes':'Jetzt'}: ${escapeHTML(next.player.name)} · ${escapeHTML(next.side===0?session.ownName:session.opponentName)}`:''}</p>`;
}

function v42CareerPending(){const own=match.people.filter(player=>player.t===0).map(player=>v42Player(player,player.keeper?activeSave.keeper:activeSave.squad.find(source=>source.n===player.n)||player)),opponent=match.people.filter(player=>player.t===1).map(player=>v42Player(player));const game=activeSave.cup.rounds[match.cup.stage][match.cup.index];return{mode:'career',stage:match.cup.stage,index:match.cup.index,regulationScore:[...match.score],ownName:activeSave.club,opponentName:match.cupOpponentName||activeOpponent().name,ownColour:match.kits?.user||currentKits().home,opponentColour:match.kits?.opponent||activeOpponent().kits.away,own,opponent,order:v42Sorted(own).map(player=>player.n),opponentOrder:v42Sorted(opponent).map(player=>player.n),score:[0,0],kicks:[],phase:'choose',home:game.home,away:game.away}}
function v42Save(){if(v42Session?.mode==='career'&&activeSave?.cup?.pending)saveCurrent()}
function v42OpenDialog(){const dialog=v42Screen.querySelector('#v42-order-dialog');if(dialog?.showModal)dialog.showModal();else dialog?.setAttribute('open','')}
function v42RenderScreen(openDialog=false){const session=v42Session;if(!session)return;startScreen.hidden=true;clubCenter.hidden=true;$('#game-screen').hidden=true;v42Screen.hidden=false;const winner=session.winner===0?session.ownName:session.opponentName,colour=session.winner===0?session.ownColour:session.opponentColour,celebration=session.phase==='done'&&session.mode==='career'&&session.stage===2?`<div class="v42-celebration">${v42Celebration(winner,colour,session.winner===0)}</div>`:'';v42Screen.innerHTML=`<section class="intro"><div><p class="eyebrow">${session.mode==='demo'?'DEMO · ELFMETERSCHIESSEN':'POKAL · ELFMETERSCHIESSEN'}</p><h1>${session.phase==='done'?`${escapeHTML(winner)} gewinnt!`:'Jetzt zählen die Nerven.'}</h1></div><p class="help">${session.mode==='career'?'Nach 90 Minuten unentschieden.':''} Drei Schützen je Team, danach abwechselnd bis zur Entscheidung.</p></section><section class="v42-arena" style="--v42-own:${escapeHTML(session.ownColour.main)};--v42-opp:${escapeHTML(session.opponentColour.main)}"><div class="v42-score"><span>${escapeHTML(session.ownName)}</span><strong>${session.score.join(' : ')}</strong><span>${escapeHTML(session.opponentName)}</span></div>${v42SceneHTML(session)}<p class="v42-last ${session.last?.goal?'good':'bad'}" role="status">${session.phase==='done'?`${escapeHTML(winner)} gewinnt im Elfmeterschießen.`:session.last?`${escapeHTML(session.last.name)}: ${v42OutcomeText(session.last)}`:'Die Mannschaften stehen bereit.'}</p>${celebration}</section><div class="v42-controls">${session.phase==='shooting'?'<button type="button" class="primary" id="v42-next">Nächster Elfmeter ↗</button>':''}${session.phase==='done'&&session.mode==='demo'?'<button type="button" class="primary" id="v42-repeat">Noch einmal ↗</button>':''}<button type="button" class="menu-action" id="v42-exit">${session.mode==='demo'?'Teams wechseln':'Zur Vereinszentrale'}</button></div><section class="panel"><h2>Schussfolge</h2><div class="v42-kicks">${session.kicks.map((kick,index)=>`<article><b>${index+1}. ${kick.side===0?escapeHTML(session.ownName):escapeHTML(session.opponentName)}</b><br>${escapeHTML(kick.name)} · <span class="${kick.goal?'goal':'miss'}">${v42OutcomeText(kick).replace(/[!.]/g,'')}</span> · ${kick.score.join(' : ')}</article>`).join('')||'<p class="help">Noch keine Schüsse.</p>'}</div></section><dialog id="v42-order-dialog" class="v42-modal"><p class="eyebrow">90 MINUTEN VORBEI</p><h2>Wähle deine Elfmeterschützen</h2><p class="help">Abschluss, Ruhe und Frische zeigen die Eignung ungefähr an. Alle sechs Spieler einschließlich Torwart schießen, bevor jemand wieder an der Reihe ist.</p><div class="v42-order-list" id="v42-order-list">${v42OrderHTML(session)}</div><button type="button" id="v42-confirm" class="primary">Reihenfolge bestätigen ↗</button></dialog>`;v42Screen.querySelectorAll('[data-v42-move]').forEach(button=>button.onclick=()=>{const i=Number(button.dataset.v42Move),j=i+Number(button.dataset.v42Dir);[session.order[i],session.order[j]]=[session.order[j],session.order[i]];v42Screen.querySelector('#v42-order-list').innerHTML=v42OrderHTML(session);v42Screen.querySelectorAll('[data-v42-move]').forEach(item=>item.onclick=button.onclick);v42Save()});v42Screen.querySelector('#v42-confirm').onclick=()=>{session.phase='shooting';v42Save();v42RenderScreen()};v42Screen.querySelector('#v42-next')?.addEventListener('click',v42NextKick);v42Screen.querySelector('#v42-repeat')?.addEventListener('click',()=>{$('#v42-demo-start').click()});v42Screen.querySelector('#v42-exit').onclick=()=>{if(session.mode==='career'&&session.phase!=='done')return;v42Screen.hidden=true;v42Session=null;if(session.mode==='career')showCenter();else{startScreen.hidden=false;drawSlots()}};if(openDialog&&session.phase==='choose')v42OpenDialog()}
function v42Celebration(name,colour,ownWin){return`<div class="cup-celebration" style="--cup-colour:${escapeHTML(colour.main)}"><h2>${ownWin?'Glückwunsch zum Pokalsieg!':'Pokalsieger!'}</h2><p>${escapeHTML(name)} gewinnt den Pokal.</p>${Array.from({length:26},(_,index)=>`<i class="confetti" style="--left:${index*41%100}%;--delay:-${index%7*.31}s;--confetti:${escapeHTML(index%2?colour.main:colour.trim)}"></i>`).join('')}</div>`}
function v42NextKick(){
 const session=v42Session;if(!session||session.phase!=='shooting')return;
 const side=session.kicks.length%2,pair=Math.floor(session.kicks.length/2),order=side===0?session.order:session.opponentOrder,roster=side===0?session.own:session.opponent,other=side===0?session.opponent:session.own,player=roster.find(item=>item.n===order[pair%6]),keeper=other.find(item=>item.keeper),goal=Math.random()<v42PenaltyChance(player,keeper);
 const saveChance=clamp(.45+((keeper.gk||70)-60)*.004+(v42Composure(keeper)-60)*.002-((player.fin||60)-60)*.001,.2,.75);
 const outcome=goal?'goal':Math.random()<saveChance?'save':Math.random()<.5?'wide':'high',shotSide=Math.random()<.5?-1:1;
 session.score[side]+=Number(goal);session.last={side,name:player.name,number:player.n,goal,outcome,shotSide,score:[...session.score]};session.kicks.push(session.last);
 const pairComplete=side===1,threeOrMore=pair>=2;if(pairComplete&&threeOrMore&&session.score[0]!==session.score[1]){session.winner=session.score[0]>session.score[1]?0:1;session.phase='done';if(session.mode==='career')v42SettleCareer(session)}v42Save();v42RenderScreen();
}
function v42SettleCareer(session){const cup=activeSave.cup,game=cup.rounds[session.stage][session.index];game.result=game.home==='user'?[...session.regulationScore]:[session.regulationScore[1],session.regulationScore[0]];game.penalties=game.home==='user'?[...session.score]:[session.score[1],session.score[0]];game.winner=session.winner===0?'user':game.home==='user'?game.away:game.home;cup.pending=null;v41PlayingCup=false;v41CupAdvance();saveCurrent()}
const v41FinishMatchV42=finishMatch;
finishMatch=function(){if(!v41PlayingCup||!match?.cup||match.score[0]!==match.score[1]){const result=v41FinishMatchV42();if(match?.cup?.stage===2){const banner=$('#match-info .cup-celebration');if(banner){if(activeSave.cup.rounds[2][0].winner!=='user')banner.querySelector('h2').textContent='Pokalsieger!';banner.setAttribute('role','status');$('#canvas').parentElement.append(banner)}}return result}v33FinishMatchV41();v41PlayingCup=false;activeSave.cup.pending=v42CareerPending();v42Session=activeSave.cup.pending;saveCurrent();v42RenderScreen(true)};
