const v42BaseRenderScreen=v42RenderScreen;
v42RenderScreen=function(openDialog=false){v42BaseRenderScreen(openDialog);const dialog=v42Screen.querySelector('#v42-order-dialog');if(v42Session?.mode==='demo')dialog.querySelector('.eyebrow').textContent='DEMO · SCHÜTZENWAHL';if(v42Session?.mode==='career'&&v42Session.phase!=='done'){const exit=v42Screen.querySelector('#v42-exit');exit.textContent='Später fortsetzen';exit.onclick=showStartScreen;dialog.insertAdjacentHTML('beforeend','<button type="button" id="v42-pause" class="menu-action wide">Später fortsetzen</button>');dialog.querySelector('#v42-pause').onclick=showStartScreen}if(v42Session?.last){const outcome=v42Session.last.outcome||(v42Session.last.goal?'goal':'wide');v42Screen.querySelector('.v42-goal-scene').classList.add(outcome);v42Screen.querySelector('.v42-ball').classList.add(outcome)}const list=v42Screen.querySelector('#v42-order-list');if(!list)return;list.querySelectorAll('[data-v42-move]').forEach(button=>button.onclick=null);list.onclick=event=>{const button=event.target.closest('[data-v42-move]');if(!button||button.disabled||!v42Session)return;const i=Number(button.dataset.v42Move),j=i+Number(button.dataset.v42Dir);[v42Session.order[i],v42Session.order[j]]=[v42Session.order[j],v42Session.order[i]];list.innerHTML=v42OrderHTML(v42Session);v42Save()}};
